import json

test_input = [
    [6, 6, 6, 5, 3, 6, 6, 6, 5, 3, 6, 6, 6, 5],
    [5, 6, 6, 6, 3, 6, 6, 6, 6, 3, 6, 6, 5, 6],
    [6, 6, 6, 6, 3, 6, 6, 6, 6, 3, 6, 6, 6, 6],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    [6, 6, 6, 5, 3, 6, 6, 6, 5, 3, 6, 6, 6, 6],
    [6, 6, 6, 6, 3, 5, 6, 6, 6, 3, 6, 6, 6, 5],
    [6, 6, 6, 6, 3, 6, 6, 6, 6, 3, 6, 6, 6, 6],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    [6, 5, 6, 6, 3, 6, 6, 6, 6, 3, 6, 6, 6, 6],
    [6, 6, 6, 6, 3, 5, 6, 6, 6, 3, 5, 6, 6, 6],
    [6, 6, 5, 6, 3, 6, 6, 6, 5, 3, 5, 6, 6, 6]
]

print("Counting 5s.")
total_5s = 0
for row in test_input:
    for val in row:
        if val == 5:
            total_5s += 1
print(f"Total 5s: {total_5s}")

print("\nRegion-by-region 5 count:")
output_grid = []

for rsec in range(3):
    row_output = []
    if rsec == 0:
        rstart, rend = 0, 3
    elif rsec == 1:
        rstart, rend = 4, 7
    else:
        rstart, rend = 8, 11

    for csec in range(3):
        count = 0
        if csec == 0:
            cstart, cend = 0, 4
        elif csec == 1:
            cstart, cend = 5, 9
        else:
            cstart, cend = 10, 14

        for r in range(rstart, rend):
            for c in range(cstart, cend):
                if test_input[r][c] == 5:
                    count += 1

        # Formula: output = 3 - count (cap at 1)
        out_val = 1 if count == 0 else 3 - count
        row_output.append(out_val)
        print(f"Region ({rsec},{csec}): count={count} → output={out_val}")

    output_grid.append(row_output)

print("\nFinal output grid:")
for row in output_grid:
    print(row)

submit_data = {"action": "submit", "grid": output_grid}
print("\nSubmitting:")
print(json.dumps(submit_data))

